-- =========================================================
-- STEP 1: MAKE ALERT_ID AUTO-GENERATED
-- =========================================================

DO $$
BEGIN

    IF NOT EXISTS (
        SELECT 1
        FROM pg_attribute a
        JOIN pg_class c
            ON a.attrelid = c.oid
        JOIN pg_namespace n
            ON c.relnamespace = n.oid
        WHERE n.nspname = 'production'
          AND c.relname = 'fraud_alerts'
          AND a.attname = 'alert_id'
          AND a.attidentity <> ''
    ) THEN

        ALTER TABLE production.fraud_alerts
        ALTER COLUMN alert_id
        ADD GENERATED BY DEFAULT AS IDENTITY;

    END IF;

END;
$$;


-- =========================================================
-- STEP 2: SYNCHRONIZE ALERT_ID IDENTITY SEQUENCE
--
-- If fraud_alerts contains records, synchronize the
-- identity sequence with MAX(alert_id).
--
-- If the table is empty, do NOT call setval().
-- The identity sequence will generate the first valid ID.
-- =========================================================

DO $$
DECLARE
    v_sequence_name TEXT;
    v_max_alert_id BIGINT;
BEGIN

    -- Get the identity sequence name
    SELECT pg_get_serial_sequence(
        'production.fraud_alerts',
        'alert_id'
    )
    INTO v_sequence_name;


    -- Get the current maximum alert ID
    SELECT MAX(alert_id)
    INTO v_max_alert_id
    FROM production.fraud_alerts;


    -- Synchronize only when existing data is present
    IF v_sequence_name IS NOT NULL
       AND v_max_alert_id IS NOT NULL THEN

        PERFORM setval(
            v_sequence_name,
            v_max_alert_id,
            true
        );

    END IF;

END;
$$;


-- =========================================================
-- PROCEDURE 1: ADD FRAUD ALERT
-- =========================================================

CREATE OR REPLACE PROCEDURE production.add_fraud_alert(
    p_transaction_id INT,
    p_alert_type VARCHAR(50),
    p_risk_score DECIMAL(5,2),
    p_description VARCHAR(255),
    p_alert_status VARCHAR(30)
)
LANGUAGE plpgsql
AS $$
BEGIN

    -- -----------------------------------------------------
    -- Validate required parameters
    -- -----------------------------------------------------

    IF p_transaction_id IS NULL THEN

        RAISE EXCEPTION
            'Transaction ID cannot be NULL';

    END IF;


    IF p_alert_type IS NULL
       OR TRIM(p_alert_type) = '' THEN

        RAISE EXCEPTION
            'Alert type cannot be NULL or empty';

    END IF;


    IF p_risk_score IS NULL THEN

        RAISE EXCEPTION
            'Risk score cannot be NULL';

    END IF;


    IF p_alert_status IS NULL THEN

        RAISE EXCEPTION
            'Alert status cannot be NULL';

    END IF;


    -- -----------------------------------------------------
    -- Validate transaction existence
    -- -----------------------------------------------------

    IF NOT EXISTS (
        SELECT 1
        FROM production.transactions
        WHERE transaction_id = p_transaction_id
    ) THEN

        RAISE EXCEPTION
            'Transaction % does not exist',
            p_transaction_id;

    END IF;


    -- -----------------------------------------------------
    -- Validate risk score
    -- -----------------------------------------------------

    IF p_risk_score < 0
       OR p_risk_score > 100 THEN

        RAISE EXCEPTION
            'Risk score must be between 0 and 100';

    END IF;


    -- -----------------------------------------------------
    -- Validate alert status
    -- -----------------------------------------------------

    IF p_alert_status NOT IN (
        'Open',
        'Investigating',
        'Resolved',
        'False Positive'
    ) THEN

        RAISE EXCEPTION
            'Invalid fraud alert status: %',
            p_alert_status;

    END IF;


    -- -----------------------------------------------------
    -- Prevent duplicate alert insertion
    -- -----------------------------------------------------

    IF EXISTS (
        SELECT 1
        FROM production.fraud_alerts
        WHERE transaction_id = p_transaction_id
          AND alert_type = p_alert_type
          AND risk_score = p_risk_score
          AND alert_status = p_alert_status
    ) THEN

        RAISE NOTICE
            'Identical fraud alert already exists for transaction %',
            p_transaction_id;

        RETURN;

    END IF;


    -- -----------------------------------------------------
    -- Insert fraud alert
    -- alert_id is generated automatically
    -- -----------------------------------------------------

    INSERT INTO production.fraud_alerts (
        transaction_id,
        alert_type,
        risk_score,
        description,
        created_at,
        alert_status
    )

    VALUES (
        p_transaction_id,
        p_alert_type,
        p_risk_score,
        p_description,
        CURRENT_TIMESTAMP,
        p_alert_status
    );


    RAISE NOTICE
        'Fraud alert added successfully for transaction %',
        p_transaction_id;

END;
$$;


-- =========================================================
-- TEST 1: ADD FRAUD ALERT
-- Idempotent test
-- =========================================================

DO $$
DECLARE
    v_transaction_id INT;
BEGIN

    SELECT transaction_id
    INTO v_transaction_id
    FROM production.transactions
    ORDER BY transaction_id
    LIMIT 1;


    IF v_transaction_id IS NOT NULL THEN

        CALL production.add_fraud_alert(
            v_transaction_id,
            'Procedure Test',
            85.50,
            'Test fraud alert generated by procedure validation',
            'Open'
        );

    ELSE

        RAISE NOTICE
            'TEST 1 skipped: No transactions found';

    END IF;

END;
$$;


-- =========================================================
-- VERIFY FRAUD ALERT
-- =========================================================

SELECT
    alert_id,
    transaction_id,
    alert_type,
    risk_score,
    alert_status
FROM production.fraud_alerts
ORDER BY alert_id DESC
LIMIT 5;


-- =========================================================
-- PROCEDURE 2: UPDATE FRAUD ALERT STATUS
-- =========================================================

CREATE OR REPLACE PROCEDURE production.update_fraud_alert_status(
    p_alert_id INT,
    p_new_status VARCHAR(30)
)
LANGUAGE plpgsql
AS $$
BEGIN

    -- -----------------------------------------------------
    -- Validate parameters
    -- -----------------------------------------------------

    IF p_alert_id IS NULL THEN

        RAISE EXCEPTION
            'Alert ID cannot be NULL';

    END IF;


    IF p_new_status IS NULL
       OR TRIM(p_new_status) = '' THEN

        RAISE EXCEPTION
            'New alert status cannot be NULL or empty';

    END IF;


    -- -----------------------------------------------------
    -- Validate status
    -- -----------------------------------------------------

    IF p_new_status NOT IN (
        'Open',
        'Investigating',
        'Resolved',
        'False Positive'
    ) THEN

        RAISE EXCEPTION
            'Invalid fraud alert status: %',
            p_new_status;

    END IF;


    -- -----------------------------------------------------
    -- Update status
    -- -----------------------------------------------------

    UPDATE production.fraud_alerts

    SET alert_status = p_new_status

    WHERE alert_id = p_alert_id;


    IF NOT FOUND THEN

        RAISE EXCEPTION
            'Fraud alert % does not exist',
            p_alert_id;

    END IF;


    RAISE NOTICE
        'Fraud alert % status updated successfully',
        p_alert_id;

END;
$$;


-- =========================================================
-- TEST 2: UPDATE LATEST PROCEDURE-TEST ALERT
-- =========================================================

DO $$
DECLARE
    v_latest_alert_id INT;
BEGIN

    SELECT alert_id
    INTO v_latest_alert_id
    FROM production.fraud_alerts
    WHERE alert_type = 'Procedure Test'
    ORDER BY alert_id DESC
    LIMIT 1;


    IF v_latest_alert_id IS NOT NULL THEN

        CALL production.update_fraud_alert_status(
            v_latest_alert_id,
            'Investigating'
        );

    ELSE

        RAISE NOTICE
            'TEST 2 skipped: No procedure-test fraud alert found';

    END IF;

END;
$$;


