-- =========================================================
-- PROCEDURE 3: TRANSFER MONEY
-- Transaction-safe money transfer
--
-- Both accounts are locked in a consistent account_id
-- order to reduce the risk of deadlocks during concurrent
-- transfers.
-- =========================================================

CREATE OR REPLACE PROCEDURE production.transfer_money(
    p_source_account_id INT,
    p_destination_account_id INT,
    p_amount DECIMAL(15,2)
)
LANGUAGE plpgsql
AS $$
DECLARE

    v_source_balance DECIMAL(15,2);
    v_source_currency VARCHAR(10);
    v_destination_currency VARCHAR(10);

BEGIN

    -- -----------------------------------------------------
    -- Validate parameters
    -- -----------------------------------------------------

    IF p_source_account_id IS NULL
       OR p_destination_account_id IS NULL THEN

        RAISE EXCEPTION
            'Source and destination account IDs cannot be NULL';

    END IF;


    IF p_amount IS NULL THEN

        RAISE EXCEPTION
            'Transfer amount cannot be NULL';

    END IF;


    -- -----------------------------------------------------
    -- Validate transfer amount
    -- -----------------------------------------------------

    IF p_amount <= 0 THEN

        RAISE EXCEPTION
            'Transfer amount must be greater than zero';

    END IF;


    -- -----------------------------------------------------
    -- Prevent transferring to the same account
    -- -----------------------------------------------------

    IF p_source_account_id = p_destination_account_id THEN

        RAISE EXCEPTION
            'Source and destination accounts must be different';

    END IF;


    -- -----------------------------------------------------
    -- Lock both accounts in a consistent order
    -- -----------------------------------------------------

    IF p_source_account_id < p_destination_account_id THEN

        -- Lock source first
        SELECT
            balance,
            currency
        INTO
            v_source_balance,
            v_source_currency
        FROM production.accounts
        WHERE account_id = p_source_account_id
        FOR UPDATE;


        IF NOT FOUND THEN

            RAISE EXCEPTION
                'Source account % does not exist',
                p_source_account_id;

        END IF;


        -- Lock destination second
        SELECT
            currency
        INTO
            v_destination_currency
        FROM production.accounts
        WHERE account_id = p_destination_account_id
        FOR UPDATE;


        IF NOT FOUND THEN

            RAISE EXCEPTION
                'Destination account % does not exist',
                p_destination_account_id;

        END IF;

    ELSE

        -- Lock destination first
        SELECT
            currency
        INTO
            v_destination_currency
        FROM production.accounts
        WHERE account_id = p_destination_account_id
        FOR UPDATE;


        IF NOT FOUND THEN

            RAISE EXCEPTION
                'Destination account % does not exist',
                p_destination_account_id;

        END IF;


        -- Lock source second
        SELECT
            balance,
            currency
        INTO
            v_source_balance,
            v_source_currency
        FROM production.accounts
        WHERE account_id = p_source_account_id
        FOR UPDATE;


        IF NOT FOUND THEN

            RAISE EXCEPTION
                'Source account % does not exist',
                p_source_account_id;

        END IF;

    END IF;


    -- -----------------------------------------------------
    -- Validate currencies
    -- -----------------------------------------------------

    IF v_source_currency <> v_destination_currency THEN

        RAISE EXCEPTION
            'Source and destination currencies do not match';

    END IF;


    -- -----------------------------------------------------
    -- Validate sufficient balance
    -- -----------------------------------------------------

    IF v_source_balance < p_amount THEN

        RAISE EXCEPTION
            'Insufficient balance';

    END IF;


    -- -----------------------------------------------------
    -- Deduct money from source account
    -- -----------------------------------------------------

    UPDATE production.accounts

    SET balance = balance - p_amount

    WHERE account_id = p_source_account_id;


    -- -----------------------------------------------------
    -- Add money to destination account
    -- -----------------------------------------------------

    UPDATE production.accounts

    SET balance = balance + p_amount

    WHERE account_id = p_destination_account_id;


    -- -----------------------------------------------------
    -- Transfer completed successfully
    -- -----------------------------------------------------

    RAISE NOTICE
        'Transfer completed successfully: % -> %, amount = %',
        p_source_account_id,
        p_destination_account_id,
        p_amount;

END;
$$;


-- =========================================================
-- TEST 3: SUCCESSFUL TRANSFER
--
-- Performs a real transfer and then reverses it.
-- This avoids using ROLLBACK inside a PL/pgSQL block.
-- =========================================================

DO $$
DECLARE

    v_source_account_id INT;
    v_destination_account_id INT;

    v_source_balance DECIMAL(15,2);
    v_source_balance_after DECIMAL(15,2);

    v_destination_balance_before DECIMAL(15,2);
    v_destination_balance_after DECIMAL(15,2);

    v_source_currency VARCHAR(10);

    v_final_source_balance DECIMAL(15,2);
    v_final_destination_balance DECIMAL(15,2);

BEGIN

    -- -----------------------------------------------------
    -- Find source account
    -- -----------------------------------------------------

    SELECT
        account_id,
        balance,
        currency
    INTO
        v_source_account_id,
        v_source_balance,
        v_source_currency
    FROM production.accounts
    WHERE balance >= 100
    ORDER BY account_id
    LIMIT 1;


    -- -----------------------------------------------------
    -- Find compatible destination account
    -- -----------------------------------------------------

    SELECT
        account_id,
        balance
    INTO
        v_destination_account_id,
        v_destination_balance_before
    FROM production.accounts
    WHERE account_id <> v_source_account_id
      AND currency = v_source_currency
    ORDER BY account_id
    LIMIT 1;


    IF v_source_account_id IS NOT NULL
       AND v_destination_account_id IS NOT NULL THEN

        BEGIN

            -- -------------------------------------------------
            -- Forward transfer
            -- -------------------------------------------------

            CALL production.transfer_money(
                v_source_account_id,
                v_destination_account_id,
                100
            );


            -- -------------------------------------------------
            -- Verify source balance
            -- -------------------------------------------------

            SELECT balance
            INTO v_source_balance_after
            FROM production.accounts
            WHERE account_id = v_source_account_id;


            -- -------------------------------------------------
            -- Verify destination balance
            -- -----------------------------------------------------

            SELECT balance
            INTO v_destination_balance_after
            FROM production.accounts
            WHERE account_id = v_destination_account_id;


            IF v_source_balance_after =
                   v_source_balance - 100

               AND v_destination_balance_after =
                   v_destination_balance_before + 100
            THEN

                RAISE NOTICE
                    'TEST 3 PASSED: Transfer balances updated correctly';

            ELSE

                RAISE EXCEPTION
                    'TEST 3 FAILED: Balance update validation failed';

            END IF;


            -- -------------------------------------------------
            -- Reverse transfer
            -- -------------------------------------------------

            CALL production.transfer_money(
                v_destination_account_id,
                v_source_account_id,
                100
            );


            -- -------------------------------------------------
            -- Verify restoration
            -- -------------------------------------------------

            SELECT balance
            INTO v_final_source_balance
            FROM production.accounts
            WHERE account_id = v_source_account_id;


            SELECT balance
            INTO v_final_destination_balance
            FROM production.accounts
            WHERE account_id = v_destination_account_id;


            IF v_final_source_balance = v_source_balance
               AND v_final_destination_balance =
                   v_destination_balance_before
            THEN

                RAISE NOTICE
                    'TEST 3 PASSED: Balances restored to original values';

            ELSE

                RAISE WARNING
                    'TEST 3 WARNING: Balances could not be fully restored - manual check required';

            END IF;


        EXCEPTION
            WHEN OTHERS THEN

                RAISE NOTICE
                    'TEST 3 FAILED: %',
                    SQLERRM;

        END;

    ELSE

        RAISE NOTICE
            'TEST 3 skipped: Two compatible accounts with sufficient balance are required';

    END IF;

END;
$$;


-- =========================================================
-- VERIFY ACCOUNT BALANCES
-- =========================================================

SELECT
    account_id,
    account_number,
    balance,
    currency
FROM production.accounts
ORDER BY account_id
LIMIT 10;


-- =========================================================
-- TEST 4: FAILED TRANSFER
-- Uses an amount larger than available balance.
--
-- The transfer must fail without changing the source
-- account balance.
-- =========================================================

DO $$
DECLARE

    v_source_account_id INT;
    v_destination_account_id INT;

    v_source_balance DECIMAL(15,2);
    v_balance_after DECIMAL(15,2);

BEGIN

    -- -----------------------------------------------------
    -- Select source account
    -- -----------------------------------------------------

    SELECT
        account_id,
        balance
    INTO
        v_source_account_id,
        v_source_balance
    FROM production.accounts
    ORDER BY account_id
    LIMIT 1;


    -- -----------------------------------------------------
    -- Select destination account
    -- -----------------------------------------------------

    SELECT account_id
    INTO v_destination_account_id
    FROM production.accounts
    WHERE account_id <> v_source_account_id
    ORDER BY account_id
    LIMIT 1;


    IF v_source_account_id IS NOT NULL
       AND v_destination_account_id IS NOT NULL THEN

        BEGIN

            -- -------------------------------------------------
            -- Attempt an impossible transfer
            -- -------------------------------------------------

            CALL production.transfer_money(
                v_source_account_id,
                v_destination_account_id,
                v_source_balance + 1000000
            );


            -- If the call succeeds, the test fails.
            RAISE EXCEPTION
                'TEST 4 FAILED: Transfer unexpectedly succeeded';


        EXCEPTION
            WHEN OTHERS THEN

                IF SQLERRM =
                   'TEST 4 FAILED: Transfer unexpectedly succeeded'
                THEN

                    RAISE;

                ELSE

                    RAISE NOTICE
                        'TEST 4 PASSED: Transfer failed as expected - %',
                        SQLERRM;

                END IF;

        END;


        -- -----------------------------------------------------
        -- Verify source balance remained unchanged
        -- -----------------------------------------------------

        SELECT balance
        INTO v_balance_after
        FROM production.accounts
        WHERE account_id = v_source_account_id;


        IF v_balance_after = v_source_balance THEN

            RAISE NOTICE
                'TEST 4 PASSED: Source balance remained unchanged';

        ELSE

            RAISE WARNING
                'TEST 4 WARNING: Source balance changed unexpectedly';

        END IF;


    ELSE

        RAISE NOTICE
            'TEST 4 skipped: At least two accounts are required';

    END IF;

END;
$$;


